package com.longjiahao.asmrplayer;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.net.HttpURLConnection;
import java.util.concurrent.*;

/** Sharing, link records, and explicit destination downloads are independent. */
public final class OnlinePanel {
 public static final int DOWNLOAD_REQUEST=105;private static final int PLAY=0,DOWNLOAD=1,SAVE=2;
 private static final String PENDING="online-download-pending",PENDING_URL="share-url",PENDING_TITLE="title";
 public interface Host {void play(OnlineResolver.Result source,String link,String title,long position);Button heart(OnlineLibrary.Entry entry);void addTo(OnlineLibrary.Entry entry);void information(OnlineLibrary.Entry entry);void next(OnlineLibrary.Entry entry);boolean busy();void downloaded(Uri uri,String name);}
 private final Activity activity;private final Host host;private final OnlineLibrary library;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService network=Executors.newFixedThreadPool(2);
 private AlertDialog resolvingDialog;private Future<?> resolvingTask;private LinearLayout rows;private TextView state;private Button cancel;private int generation;private boolean destroyed;private volatile boolean downloading,cancelled;private volatile HttpURLConnection connection;private OnlineResolver.Result pendingDownload;private String downloadName;
 public OnlinePanel(Activity activity,Host host){this.activity=activity;this.host=host;library=new OnlineLibrary(activity);}
 public View createView(){ScrollView scroll=new ScrollView(activity);rows=column();rows.setPadding(dp(18),dp(16),dp(18),dp(20));scroll.addView(rows);render();return scroll;}
 private void render(){if(rows==null)return;rows.removeAllViews();LinearLayout heading=new LinearLayout(activity);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(text("在线",25,true),new LinearLayout.LayoutParams(0,-2,1));Button add=button("添加链接");heading.addView(add);add.setOnClickListener(v->paste());rows.addView(heading);rows.addView(text("仅支持B站链接；保存链接不保存完整视频",13,false));
  state=text(downloading?"正在下载，请保持软件打开":"",13,false);rows.addView(state);cancel=button("取消下载");cancel.setVisibility(downloading?View.VISIBLE:View.GONE);rows.addView(cancel);cancel.setOnClickListener(v->cancelDownload());
  if(library.list().isEmpty()){TextView empty=text("还没有保存在线链接\n可从B站分享，也可添加B站链接",16,false);empty.setPadding(0,dp(28),0,dp(28));rows.addView(empty);}
  for(OnlineLibrary.Entry entry:library.list()){LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(16),dp(4),dp(16));LibraryStyle.card(row,false);ImageView platform=new ImageView(activity);UiIcon icon=new UiIcon(entry.platform(),Color.WHITE);platform.setImageDrawable(icon);platform.setContentDescription(entry.platform().equals("bili")?"B站":"抖音");row.addView(platform,new LinearLayout.LayoutParams(dp(38),dp(38)));TextView title=text(entry.title()+(entry.platform().equals("bili")?"":" · 不再支持"),16,true);title.setMaxLines(2);title.setPadding(dp(12),0,dp(4),0);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));row.addView(host.heart(entry),new LinearLayout.LayoutParams(dp(48),dp(48)));Button more=LibraryStyle.more(activity,entry.title());more.setContentDescription(entry.title()+"操作");row.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));row.setOnClickListener(v->start(entry,PLAY,false,true,0));more.setOnClickListener(v->{if(!entry.platform().equals("bili")){legacyMenu(entry);return;}new AlertDialog.Builder(activity).setTitle(entry.title()).setItems(new String[]{"在线播放","下载视频","重命名","在原平台打开","移出在线列表","加入清单","信息","下一首播放"},(d,which)->{if(which==0)start(entry,PLAY,false,true,0);else if(which==1)start(entry,DOWNLOAD,false,true,0);else if(which==2)rename(entry);else if(which==3)openOriginal(entry.url());else if(which==4){library.remove(entry.url());render();}else if(which==5)host.addTo(entry);else if(which==6)host.information(entry);else host.next(entry);}).setNegativeButton("返回",null).show();});LibraryStyle.addCard(rows,row);}
 }
 public java.util.List<MediaRef> references(){java.util.List<MediaRef> result=new java.util.ArrayList<>();for(OnlineLibrary.Entry e:library.list())if(e.platform().equals("bili"))result.add(MediaRef.online(e));return result;}
 public void refreshLibrary(){render();}
 public void acceptIntent(Intent intent){if(Intent.ACTION_SEND.equals(intent.getAction())){String value=intent.getStringExtra(Intent.EXTRA_TEXT);if(value!=null)showShare(value);intent.setAction(null);}}
 private void paste(){EditText input=new EditText(activity);input.setHint("粘贴链接或完整分享文字");new AlertDialog.Builder(activity).setTitle("添加在线链接").setView(input).setPositiveButton("继续",(d,w)->showShare(input.getText().toString())).setNegativeButton("取消",null).show();}
 public void showShare(String text){try{OnlineLink.Link link=OnlineLink.parse(text);String seed=text.replaceAll("https?://\\S+","").trim();if(seed.isBlank() || seed.length()>160)seed="B站视频";final String initial=seed;LinearLayout panel=column();panel.setPadding(dp(22),dp(8),dp(22),dp(8));EditText title=new EditText(activity);title.setText(initial);title.setHint("作品名称，可修改");panel.addView(title);CheckBox save=new CheckBox(activity);save.setText("保存链接到在线列表");save.setTextColor(Color.WHITE);panel.addView(save);panel.addView(text("在线播放和下载会先检查平台是否提供可用地址。",13,false));AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("接收在线链接").setView(panel).setPositiveButton("在线播放",null).setNegativeButton("下载视频",null).setNeutralButton("仅保存链接",null).create();dialog.setOnShowListener(d->{for(int mode=0;mode<3;mode++){final int action=mode;int which=mode==0?AlertDialog.BUTTON_POSITIVE:mode==1?AlertDialog.BUTTON_NEGATIVE:AlertDialog.BUTTON_NEUTRAL;dialog.getButton(which).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isBlank()){title.setError("请输入名称");return;}dialog.dismiss();start(new OnlineLibrary.Entry(link.url(),name,link.platform()),action,save.isChecked() || action==SAVE,!name.equals(initial),0);});}});dialog.show();}catch(IllegalArgumentException error){message(error.getMessage());}}
 private void legacyMenu(OnlineLibrary.Entry entry){new AlertDialog.Builder(activity).setTitle("不再支持此平台链接").setItems(new String[]{"重命名","在原平台打开","移出在线列表","加入清单","信息"},(d,which)->{if(which==0)rename(entry);else if(which==1)openOriginal(entry.url());else if(which==2){library.remove(entry.url());render();}else if(which==3)host.addTo(entry);else host.information(entry);}).setNegativeButton("返回",null).show();}
 private void rename(OnlineLibrary.Entry entry){EditText title=new EditText(activity);title.setText(entry.title());AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("重命名链接").setView(title).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isBlank()){title.setError("请输入名称");return;}library.save(new OnlineLibrary.Entry(entry.url(),name,entry.platform()));render();dialog.dismiss();}));dialog.show();}
 public void restore(String url,String title,long position){try{OnlineLink.Link link=OnlineLink.parse(url);start(new OnlineLibrary.Entry(link.url(),title,link.platform()),PLAY,false,true,position);}catch(IllegalArgumentException error){message(error.getMessage());}}
 private void start(OnlineLibrary.Entry entry,int action,boolean save,boolean keepTitle,long position){if(!entry.platform().equals("bili")){message("1.7已移除抖音链接功能，旧记录可查看或移除");return;}if(action==DOWNLOAD && (downloading || pendingDownload!=null || host.busy())){message("正在保存或处理文件，请完成后再下载");return;}if(save){library.save(entry);render();}cancelResolve();int token=++generation;AlertDialog wait=new AlertDialog.Builder(activity).setTitle(action==SAVE?"正在获取名称":"正在解析在线链接").setMessage("首次加载可能需要一些时间").setNegativeButton("取消",(d,w)->cancelResolve()).create();wait.setOnCancelListener(d->cancelResolve());resolvingDialog=wait;wait.show();resolvingTask=network.submit(()->{try{OnlineResolver.Result result=new OnlineResolver(activity).resolve(entry,action!=SAVE);main.post(()->{if(destroyed || token!=generation){if(!destroyed)wait.dismiss();return;}wait.dismiss();String name=keepTitle?entry.title():result.title();if(save){library.save(new OnlineLibrary.Entry(entry.url(),name,entry.platform()));render();}if(action==SAVE){message("链接已保存");return;}if(result.mediaUrl()==null){failure(entry,"当前未取得播放器可访问的完整MP4地址。链接可以保存，稍后重试或在原平台打开。");return;}if(action==PLAY)host.play(result,entry.url(),name,position);else chooseDownload(result,name);});}catch(Exception error){main.post(()->{if(destroyed || token!=generation){if(!destroyed)wait.dismiss();return;}wait.dismiss();failure(entry,"解析失败："+error.getMessage()+(save?"。链接记录已保留":""));});}});}
 private void chooseDownload(OnlineResolver.Result result,String name){if(downloading || pendingDownload!=null || host.busy()){message("正在保存或处理文件，请完成后再下载");return;}pendingDownload=result;downloadName=OnlineLink.safeName(name)+".mp4";activity.getSharedPreferences(PENDING,Context.MODE_PRIVATE).edit().putString(PENDING_URL,result.shareUrl()).putString(PENDING_TITLE,name).apply();Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("video/mp4").putExtra(Intent.EXTRA_TITLE,downloadName);try{activity.startActivityForResult(intent,DOWNLOAD_REQUEST);}catch(RuntimeException error){pendingDownload=null;clearPending();message("没有可用的文件保存界面");}}
 public void activityResult(int resultCode,Intent data){OnlineResolver.Result source=pendingDownload;pendingDownload=null;String url=activity.getSharedPreferences(PENDING,Context.MODE_PRIVATE).getString(PENDING_URL,null);String savedName=activity.getSharedPreferences(PENDING,Context.MODE_PRIVATE).getString(PENDING_TITLE,null);if(resultCode!=Activity.RESULT_OK || data==null || data.getData()==null){clearPending();message("已取消下载");return;}if(downloading || host.busy()){clearPending();message("正在保存或处理文件，请完成后再下载");return;}Uri destination=data.getData();try{if((data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0)activity.getContentResolver().takePersistableUriPermission(destination,Intent.FLAG_GRANT_READ_URI_PERMISSION);if((data.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0)activity.getContentResolver().takePersistableUriPermission(destination,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(SecurityException ignored){}final String name=downloadName!=null?downloadName:OnlineLink.safeName(savedName==null?"在线视频":savedName)+".mp4";if(source==null && url!=null){try{OnlineLink.Link link=OnlineLink.parse(url);OnlineLibrary.Entry entry=new OnlineLibrary.Entry(link.url(),savedName==null?"在线视频":savedName,link.platform());downloading=true;render();activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);resolvingTask=network.submit(()->{try{OnlineResolver.Result fresh=new OnlineResolver(activity).resolve(entry,true);main.post(()->{if(destroyed)return;downloading=false;activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(fresh.mediaUrl()==null){clearPending();render();message("应用重建后重新解析失败，请从在线列表重试");return;}pendingDownload=fresh;downloadName=name;activityResult(Activity.RESULT_OK,data);});}catch(Exception error){main.post(()->{if(destroyed)return;downloading=false;activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);clearPending();render();message("应用重建后重新解析失败，请从在线列表重试："+error.getMessage());});}});return;}catch(IllegalArgumentException error){clearPending();message("下载记录无效，请从在线列表重试");return;}}if(source==null){clearPending();message("下载任务已失效，请从在线列表重试");return;}clearPending();beginDownload(source,name,destination);}
 private void clearPending(){activity.getSharedPreferences(PENDING,Context.MODE_PRIVATE).edit().clear().apply();downloadName=null;}
 private void beginDownload(OnlineResolver.Result source,String name,Uri destination){downloading=true;cancelled=false;render();activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  network.execute(()->{String outcome;boolean ok=false;HttpURLConnection c=null;try{c=OnlineResolver.connect(source.mediaUrl(),source.referer());connection=c;if(cancelled)throw new IOException("已取消");int code=c.getResponseCode();if(code!=200)throw new IOException("媒体地址已失效或暂时拒绝下载（"+code+"），请重新解析");long expected=c.getContentLengthLong(),total=0;try(InputStream input=c.getInputStream();OutputStream output=activity.getContentResolver().openOutputStream(destination,"w")){if(output==null)throw new IOException("保存位置不可写");byte[] header=new byte[12];int pos=0;while(pos<12){int got=input.read(header,pos,12-pos);if(got<0)throw new IOException("媒体内容为空或不完整");pos+=got;}if( header[4]!='f' || header[5]!='t' || header[6]!='y' || header[7]!='p')throw new IOException("平台返回的内容不是MP4，已停止");output.write(header);total=header.length;byte[] block=new byte[262144];int n;long last=0;while((n=input.read(block))!=-1){if(cancelled || Thread.currentThread().isInterrupted())throw new IOException("下载已取消");output.write(block,0,n);total+=n;long now=SystemClock.elapsedRealtime();if(now-last>500){last=now;final long bytes=total;main.post(()->{if(!destroyed)state.setText(expected>0?"正在下载："+(bytes*100/expected)+"%":"已下载 "+(bytes/1048576)+"MB");});}}if(cancelled)throw new IOException("下载已取消");if(expected>0 && total!=expected)throw new IOException("连接提前结束，文件不完整");output.flush();}ok=true;outcome="下载完成，已加入视频列表";}catch(Exception error){outcome="下载未完成："+error.getMessage()+"。保存位置可能留下未完成文件，请检查后自行处理。";}finally{if(c!=null)c.disconnect();connection=null;}final boolean success=ok;final String text=outcome;main.post(()->{if(destroyed)return;downloading=false;activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);render();state.setText(text);if(success)host.downloaded(destination,name);message(text);});});
 }
 private void cancelDownload(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();state.setText("正在取消下载…");}
 public boolean downloading(){return downloading;}
 public void cancelResolve(){generation++;if(resolvingTask!=null)resolvingTask.cancel(true);if(resolvingDialog!=null){resolvingDialog.dismiss();resolvingDialog=null;}}
 public void close(){cancelResolve();destroyed=true;cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();network.shutdownNow();main.removeCallbacksAndMessages(null);}
 private void failure(OnlineLibrary.Entry entry,String text){new AlertDialog.Builder(activity).setTitle("暂时无法播放或下载").setMessage(text).setPositiveButton("在原平台打开",(d,w)->openOriginal(entry.url())).setNegativeButton("返回",null).show();}
 private void openOriginal(String url){try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(RuntimeException error){message("没有可以打开这个链接的应用");}}
 private void message(String text){Toast.makeText(activity,text,Toast.LENGTH_LONG).show();}
 private LinearLayout column(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private TextView text(String value,int size,boolean bold){TextView t=new TextView(activity);t.setText(value);t.setTextColor(bold?Color.WHITE:Color.LTGRAY);t.setTextSize(size);if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);return t;}
 private Button button(String value){Button b=new Button(activity);b.setText(value);b.setAllCaps(false);b.setTextColor(0xFF92D8C0);b.setBackgroundColor(Color.TRANSPARENT);b.setElevation(0);b.setStateListAnimator(null);return b;}
 private int dp(int value){return Math.round(value*activity.getResources().getDisplayMetrics().density);}
}
